from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.adjustments import outage_refund
from ledgerly.models import Payment
from ledgerly.errors import BillingError
from ledgerly import audit

T0 = datetime(2026,10,1,tzinfo=timezone.utc)
def mk(amt="80.00", status="captured"):
    return Payment("p","i",Decimal(amt),status=status,created_at=T0,captured_at=T0)

# full refund sets status
p=mk(); outage_refund(p,Decimal("80.00"),T0); print("full:",p.refunded_amount,p.status)
# partial
p=mk(); outage_refund(p,Decimal("8.00"),T0); print("partial:",p.refunded_amount,p.status)
# over refund
p=mk(); 
try: outage_refund(p,Decimal("81.00"),T0)
except BillingError as e: print("over:",e.code)
# non positive
p=mk()
try: outage_refund(p,Decimal("0"),T0)
except BillingError as e: print("zero:",e.code)
# not captured
p=mk(status="authorized")
try: outage_refund(p,Decimal("1.00"),T0)
except BillingError as e: print("state:",e.code)
# approval threshold
p=mk("5000.00")
try: outage_refund(p,Decimal("1000.01"),T0)
except BillingError as e: print("approval:",e.code)
p=mk("5000.00"); outage_refund(p,Decimal("1000.00"),T0); print("at threshold ok:",p.refunded_amount)
p=mk("5000.00"); outage_refund(p,Decimal("1000.01"),T0,approved_by="mgr"); print("approved ok:",p.refunded_amount)
# idempotency
audit.clear()
p=mk("5000.00")
outage_refund(p,Decimal("10.00"),T0,idempotency_key="k1")
r=outage_refund(p,Decimal("10.00"),T0,idempotency_key="k1")
print("idem:",p.refunded_amount, r is p, len(audit.events("outage_refund")))
